using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly ProviderStub provider = new();
    private readonly HttpClient client;
    private readonly HttpPaymentGateway gateway;

    public HttpPaymentGatewayTests()
    {
        client = new HttpClient { BaseAddress = provider.BaseAddress };
        gateway = new HttpPaymentGateway(client);
    }

    [Fact]
    public async Task The_request_is_a_JSON_POST_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await gateway.AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        var received = Assert.Single(provider.Requests);
        Assert.Equal("POST", received.Method);
        Assert.Equal("/v1/authorizations", received.Path);
        Assert.StartsWith("application/json", received.ContentType);
        using var json = JsonDocument.Parse(received.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_refusal_with_402_is_a_decline_not_an_error()
    {
        provider.Respond(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_does_not_say_approved_is_never_treated_as_approved(string body)
    {
        provider.Respond(200, body);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_that_is_not_JSON_fails_loudly()
    {
        provider.Respond(200, "<html>oops</html>");

        await Assert.ThrowsAnyAsync<JsonException>(Authorize);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Errors_other_than_a_refusal_surface_as_failures_and_are_not_declines(int status)
    {
        provider.Respond(status, """{"status":"approved"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        gateway.AuthorizeAsync("ORD-7", new Money(12, "EUR"), CancellationToken.None);

    public void Dispose()
    {
        client.Dispose();
        provider.Dispose();
    }

    private sealed record ReceivedRequest(string Method, string Path, string? ContentType, string Body);

    // A real HTTP server on loopback standing in for the provider.
    private sealed class ProviderStub : IDisposable
    {
        private readonly HttpListener listener = new();
        private readonly Task loop;
        private volatile int status = 200;
        private volatile string body = "";

        public ProviderStub()
        {
            int port;
            using (var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0))
            {
                probe.Start();
                port = ((IPEndPoint)probe.LocalEndpoint).Port;
            }
            BaseAddress = new Uri($"http://127.0.0.1:{port}/");
            listener.Prefixes.Add(BaseAddress.ToString());
            listener.Start();
            loop = Task.Run(Serve);
        }

        public Uri BaseAddress { get; }

        public System.Collections.Concurrent.ConcurrentQueue<ReceivedRequest> Requests { get; } = new();

        public void Respond(int statusCode, string responseBody)
        {
            status = statusCode;
            body = responseBody;
        }

        private async Task Serve()
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                var request = context.Request;
                using var reader = new StreamReader(request.InputStream, Encoding.UTF8);
                Requests.Enqueue(new ReceivedRequest(
                    request.HttpMethod, request.Url!.AbsolutePath, request.ContentType, await reader.ReadToEndAsync()));

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                context.Response.ContentLength64 = bytes.Length;
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        public void Dispose()
        {
            listener.Close();
            loop.Wait(TimeSpan.FromSeconds(5));
        }
    }
}
